md += ['','## Per-use assessment','']
for r in active:
    md += [f'### {r["key"]}','']
    for u in r['uses']:md.append(f'- `{u["file"]}:{u["line"]}` — **{u["verdict"]}**. {u["note"]}')
    md += ['',f'Source: [{r["sources"][-1]["type"]}]({r["sources"][-1]["url"]}).','']
md += ['## Completion check','',f'Declared input hashes unchanged: **{not changed}**. Changed files: {changed or "none"}.','No manuscript/bibliography corrections were applied by this reviewer. No compilation was run because only audit artifacts changed. The parent reviewer is responsible for authorized fixes and the subsequent manuscript build.','']
(P/'CITATION_AUDIT.md').write_text('\n'.join(md),encoding='utf-8')
